import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (_req: Request, res: Response) => {
  const bookmarks = bookmarkService.getAll();
  res.status(200).json(bookmarks);
});

bookmarksRouter.get('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
});

bookmarksRouter.delete('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
});

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const data = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
});

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with generated id and createdAt timestamp', () => {
      const bookmark = service.create({
        url: 'https://example.com',
        title: 'Example',
        tags: ['web', 'test'],
      });

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe('https://example.com');
      expect(bookmark.title).toBe('Example');
      expect(bookmark.tags).toEqual(['web', 'test']);
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toISOString()).toBe(bookmark.createdAt);
    });

    it('should create a bookmark without optional title or tags', () => {
      const bookmark = service.create({
        url: 'https://example.org',
      });

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe('https://example.org');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating with an existing URL', () => {
      service.create({
        url: 'https://duplicate.com',
        title: 'First',
      });

      expect(() => {
        service.create({
          url: 'https://duplicate.com',
          title: 'Second',
        });
      }).toThrow(DuplicateBookmarkError);
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id via getById', () => {
      const created = service.create({
        url: 'https://retrieval.com',
        title: 'Retrieval Test',
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toBeDefined();
      expect(retrieved?.id).toBe(created.id);
      expect(retrieved?.url).toBe('https://retrieval.com');
    });

    it('should return undefined when retrieving a nonexistent id', () => {
      const result = service.getById('non-existent-id');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks via getAll', () => {
      service.create({ url: 'https://first.com' });
      service.create({ url: 'https://second.com' });

      const all = service.getAll();
      expect(all).toHaveLength(2);
      expect(all.map((b) => b.url)).toContain('https://first.com');
      expect(all.map((b) => b.url)).toContain('https://second.com');
    });

    it('should support deleting a bookmark', () => {
      const created = service.create({ url: 'https://delete-me.com' });
      const deleted = service.delete(created.id);
      expect(deleted).toBe(true);

      const found = service.getById(created.id);
      expect(found).toBeUndefined();
    });

    it('should clear all bookmarks via clear()', () => {
      service.create({ url: 'https://one.com' });
      service.create({ url: 'https://two.com' });
      service.clear();

      expect(service.getAll()).toHaveLength(0);
    });
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface BookmarkResponse {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

function isBookmarkResponse(data: unknown): data is BookmarkResponse {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const item = data as Record<string, unknown>;
  return (
    typeof item.id === 'string' &&
    typeof item.url === 'string' &&
    typeof item.createdAt === 'string'
  );
}

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should create a new bookmark and return 201 Created', async () => {
      const payload = {
        url: 'https://example.com/integration',
        title: 'Integration Test Bookmark',
        tags: ['integration', 'test'],
      };

      const response = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload)
        .expect(201);

      const body: unknown = response.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.id).toBeDefined();
        expect(body.url).toBe(payload.url);
        expect(body.title).toBe(payload.title);
        expect(body.tags).toEqual(payload.tags);
        expect(body.createdAt).toBeDefined();
      }
    });
  });

  describe('GET /api/v1/bookmarks', () => {
    it('should return a list of all bookmarks with 200 OK', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/first' })
        .expect(201);

      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/second' })
        .expect(201);

      const response = await request(app)
        .get('/api/v1/bookmarks')
        .expect(200);

      const body: unknown = response.body;
      expect(Array.isArray(body)).toBe(true);
      if (Array.isArray(body)) {
        expect(body).toHaveLength(2);
        expect(body.every(isBookmarkResponse)).toBe(true);
      }
    });
  });

  describe('GET /api/v1/bookmarks/:id', () => {
    it('should return a single bookmark by ID with 200 OK', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({
          url: 'https://example.com/single',
          title: 'Single Bookmark',
        })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      const response = await request(app)
        .get(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(200);

      const body: unknown = response.body;
      expect(isBookmarkResponse(body)).toBe(true);
      if (isBookmarkResponse(body)) {
        expect(body.id).toBe(createdBody.id);
        expect(body.url).toBe('https://example.com/single');
        expect(body.title).toBe('Single Bookmark');
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete an existing bookmark with 204 No Content', async () => {
      const created = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://example.com/delete-target' })
        .expect(201);

      const createdBody: unknown = created.body;
      expect(isBookmarkResponse(createdBody)).toBe(true);
      if (!isBookmarkResponse(createdBody)) {
        return;
      }

      await request(app)
        .delete(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(204);

      await request(app)
        .get(`/api/v1/bookmarks/${createdBody.id}`)
        .expect(404);
    });
  });
});

