I have implemented pagination for `GET /api/v1/bookmarks`:

1. **Service Layer (`src/services/bookmark-service.ts`)**:
   - Added `PaginatedResult<T>` interface:
     ```ts
     export interface PaginatedResult<T> {
       data: T[];
       pagination: {
         page: number;
         limit: number;
         total: number;
         totalPages: number;
       };
     }
     ```
   - Added `getPaginated(page: number, limit: number): PaginatedResult<Bookmark>` to `BookmarkService`, calculating `total`, `totalPages = Math.ceil(total / limit)`, and slicing sorted results according to `page` and `limit`.

2. **Route Handler & Parameter Parsing (`src/routes/bookmarks.ts`)**:
   - Implemented `parsePaginationParams(query: unknown)` with strict type narrowing and validation:
     - Defaults to `page = 1`, `limit = 20`.
     - Normalizes non-positive `page` values (`< 1`) to `1`.
     - Clamps non-positive `limit` values (`< 1`) to `1`, and caps `limit > 100` to `100`.
   - Updated `GET /api/v1/bookmarks` to extract query parameters, query `bookmarkService.getPaginated(page, limit)`, and return the `{ data, pagination }` structure with status 200.

3. **Tests & Validation**:
   - Added unit tests in `src/services/bookmark-service.test.ts` verifying page slicing and pagination metadata calculations.
   - Updated integration test in `tests/bookmarks.integration.test.ts` to validate the `{ data, pagination }` envelope using a type guard `isPaginatedBookmarkResponse`.
   - Verified strict type checking (`strict: true`) with zero `any` usage (`npm run typecheck`).
   - Ran all tests (`npm test`): all 22 tests passing across 3 test suites.

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  public getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

