  it('should use default values (page 1, limit 20) when query is empty or invalid', () => {
    expect(parsePaginationParams(undefined)).toEqual({ page: 1, limit: 20 });
    expect(parsePaginationParams(null)).toEqual({ page: 1, limit: 20 });
    expect(parsePaginationParams({})).toEqual({ page: 1, limit: 20 });
  });

  it('should normalize page 0 and negative pages to page 1', () => {
    expect(parsePaginationParams({ page: '0' })).toEqual({ page: 1, limit: 20 });
    expect(parsePaginationParams({ page: '-5' })).toEqual({ page: 1, limit: 20 });
    expect(parsePaginationParams({ page: 0 })).toEqual({ page: 1, limit: 20 });
    expect(parsePaginationParams({ page: -10 })).toEqual({ page: 1, limit: 20 });
  });

  it('should clamp negative limit or zero limit to 1', () => {
    expect(parsePaginationParams({ limit: '-1' })).toEqual({ page: 1, limit: 1 });
    expect(parsePaginationParams({ limit: '-10' })).toEqual({ page: 1, limit: 1 });
    expect(parsePaginationParams({ limit: '0' })).toEqual({ page: 1, limit: 1 });
    expect(parsePaginationParams({ limit: -5 })).toEqual({ page: 1, limit: 1 });
    expect(parsePaginationParams({ limit: 0 })).toEqual({ page: 1, limit: 1 });
  });

  it('should cap limit > 100 at 100', () => {
    expect(parsePaginationParams({ limit: '101' })).toEqual({ page: 1, limit: 100 });
    expect(parsePaginationParams({ limit: '500' })).toEqual({ page: 1, limit: 100 });
    expect(parsePaginationParams({ limit: 150 })).toEqual({ page: 1, limit: 100 });
  });

  it('should preserve valid page and limit values', () => {
    expect(parsePaginationParams({ page: '3', limit: '50' })).toEqual({ page: 3, limit: 50 });
    expect(parsePaginationParams({ page: 2, limit: 15 })).toEqual({ page: 2, limit: 15 });
  });
});

