describe('update', () => {
  it('should partially update title and preserve other fields', () => {
    const created = service.create({
      url: 'https://example.com/update-test',
      title: 'Original Title',
      tags: ['original'],
    });

    const updated = service.update(created.id, { title: 'Updated Title' });
    expect(updated).toBeDefined();
    expect(updated?.id).toBe(created.id);
    expect(updated?.url).toBe(created.url);
    expect(updated?.title).toBe('Updated Title');
    expect(updated?.tags).toEqual(['original']);
    expect(updated?.createdAt).toBe(created.createdAt);
  });

  it('should partially update tags and preserve other fields', () => {
    const created = service.create({
      url: 'https://example.com/update-tags',
      title: 'Original Title',
      tags: ['tag1'],
    });

    const updated = service.update(created.id, { tags: ['newtag1', 'newtag2'] });
    expect(updated).toBeDefined();
    expect(updated?.title).toBe('Original Title');
    expect(updated?.tags).toEqual(['newtag1', 'newtag2']);
  });

  it('should return undefined when updating non-existent id', () => {
    const result = service.update('non-existent-id', { title: 'Ghost' });
    expect(result).toBeUndefined();
  });
});

