describe('PATCH /api/v1/bookmarks/:id', () => {
  it('should partially update title and return 200 OK', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com/patch-title',
        title: 'Initial Title',
        tags: ['initial'],
      })
      .expect(201);

    const createdBody: unknown = created.body;
    expect(isBookmarkResponse(createdBody)).toBe(true);
    if (!isBookmarkResponse(createdBody)) {
      return;
    }

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ title: 'Patched Title' })
      .expect(200);

    const body: unknown = response.body;
    expect(isBookmarkResponse(body)).toBe(true);
    if (isBookmarkResponse(body)) {
      expect(body.id).toBe(createdBody.id);
      expect(body.url).toBe('https://example.com/patch-title');
      expect(body.title).toBe('Patched Title');
      expect(body.tags).toEqual(['initial']);
    }
  });

  it('should partially update tags and return 200 OK', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://example.com/patch-tags',
        title: 'Initial Title',
        tags: ['initial'],
      })
      .expect(201);

    const createdBody: unknown = created.body;
    expect(isBookmarkResponse(createdBody)).toBe(true);
    if (!isBookmarkResponse(createdBody)) {
      return;
    }

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ tags: ['updated1', 'updated2'] })
      .expect(200);

    const body: unknown = response.body;
    expect(isBookmarkResponse(body)).toBe(true);
    if (isBookmarkResponse(body)) {
      expect(body.id).toBe(createdBody.id);
      expect(body.url).toBe('https://example.com/patch-tags');
      expect(body.title).toBe('Initial Title');
      expect(body.tags).toEqual(['updated1', 'updated2']);
    }
  });

  it('should return 404 when updating non-existent bookmark ID', async () => {
    const response = await request(app)
      .patch('/api/v1/bookmarks/non-existent-id-123')
      .send({ title: 'New Title' })
      .expect(404);

    expect(response.body).toEqual({
      error: 'Bookmark not found: non-existent-id-123',
    });
  });

  it('should reject URL change attempts with 400 Bad Request', async () => {
    const created = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://example.com/immutable-url' })
      .expect(201);

    const createdBody: unknown = created.body;
    expect(isBookmarkResponse(createdBody)).toBe(true);
    if (!isBookmarkResponse(createdBody)) {
      return;
    }

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${createdBody.id}`)
      .send({ url: 'https://example.com/new-url' })
      .expect(400);

    expect(response.body).toEqual({
      error: 'URL is immutable and cannot be updated',
    });
  });
});

