import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a unique ID and ISO timestamp.
   *
   * @param dto - Data transfer object containing URL, optional title, and optional tags.
   * @returns The newly created bookmark.
   * @throws {DuplicateBookmarkError} If a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example',
   *   tags: ['web'],
   * });
   * ```
   */
  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to retrieve.
   * @returns The matching bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted in descending order by creation date.
   *
   * @returns An array of all stored bookmarks.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * ```
   */
  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated slice of bookmarks sorted by creation date descending.
   *
   * @param page - Page number (1-indexed).
   * @param limit - Maximum number of bookmarks per page.
   * @returns An object containing the sliced bookmark items and pagination metadata.
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 20);
   * console.log(result.data, result.pagination.totalPages);
   * ```
   */
  public getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to delete.
   * @returns True if a bookmark was deleted, false if no matching bookmark was found.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Updates an existing bookmark's title and/or tags.
   *
   * @param id - The UUID of the bookmark to update.
   * @param dto - Data transfer object containing updated title and/or tags.
   * @returns The updated bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'Updated Title',
   * });
   * ```
   */
  public update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by case-insensitive substring match on title or exact match on tags.
   *
   * @param query - The search query term.
   * @returns An array of bookmarks matching either title substring or tag exact match.
   *
   * @example
   * ```ts
   * const matches = bookmarkService.search('typescript');
   * ```
   */
  public search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Clears all stored bookmarks.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * ```
   */
  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

/**
 * Parses and normalizes pagination parameters from an incoming request query.
 *
 * @param query - The request query object or unknown input.
 * @returns An object containing normalized `page` and `limit`.
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: unknown): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  if (typeof query !== 'object' || query === null) {
    return { page, limit };
  }

  const record = query as Record<string, unknown>;

  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed < 1 ? 1 : parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = record.page < 1 ? 1 : Math.floor(record.page);
  }

  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      if (parsed < 1) {
        limit = 1;
      } else if (parsed > 100) {
        limit = 100;
      } else {
        limit = parsed;
      }
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    const parsed = Math.floor(record.limit);
    if (parsed < 1) {
      limit = 1;
    } else if (parsed > 100) {
      limit = 100;
    } else {
      limit = parsed;
    }
  }

  return { page, limit };
}

/**
 * Route handler for GET / - Lists bookmarks with pagination support.
 *
 * @param req - Express request object containing optional page and limit query parameters.
 * @param res - Express response object used to send paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query: unknown = req.query;
  const { page, limit } = parsePaginationParams(query);
  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
}

/**
 * Route handler for GET /search - Searches bookmarks by title or tag.
 *
 * @param req - Express request object containing required search query parameter q.
 * @param res - Express response object used to send search results or error response.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.get('/search', searchBookmarksHandler);
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const q = typeof req.query.q === 'string' ? req.query.q.trim() : undefined;
  if (!q) {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }
  const results = bookmarkService.search(q);
  res.status(200).json(results);
}

/**
 * Route handler for GET /:id - Retrieves a single bookmark by its ID.
 *
 * @param req - Express request object containing the bookmark ID parameter.
 * @param res - Express response object used to send the bookmark or 404 response.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.get('/:id', getBookmarkByIdHandler);
 * ```
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
}

/**
 * Route handler for DELETE /:id - Deletes a bookmark by its ID.
 *
 * @param req - Express request object containing the bookmark ID parameter.
 * @param res - Express response object used to send 204 No Content or 404 response.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.delete('/:id', deleteBookmarkHandler);
 * ```
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
}

/**
 * Route handler for PATCH /:id - Updates an existing bookmark's title and/or tags.
 *
 * @param req - Express request object containing the bookmark ID and update payload.
 * @param res - Express response object used to send the updated bookmark or error response.
 * @param next - Express next middleware function used for validation error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.patch('/:id', updateBookmarkHandler);
 * ```
 */
export function updateBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  try {
    const data = updateBookmarkSchema.parse(body);
    const updated = bookmarkService.update(id, data);
    if (!updated) {
      res.status(404).json({ error: `Bookmark not found: ${id}` });
      return;
    }
    res.status(200).json(updated);
  } catch (error: unknown) {
    next(error);
  }
}

/**
 * Route handler for POST / - Creates a new bookmark.
 *
 * @param req - Express request object containing the bookmark creation payload.
 * @param res - Express response object used to send the created bookmark with 201 status.
 * @param next - Express next middleware function used for error delegation.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.post('/', createBookmarkHandler);
 * ```
 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  try {
    const body: unknown = req.body;
    const data = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
    next(error);
  }
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', listBookmarksHandler);
bookmarksRouter.get('/search', searchBookmarksHandler);
bookmarksRouter.get('/:id', getBookmarkByIdHandler);
bookmarksRouter.delete('/:id', deleteBookmarkHandler);
bookmarksRouter.patch('/:id', updateBookmarkHandler);
bookmarksRouter.post('/', createBookmarkHandler);

